// Functions preceded by "ost" run in the "operating-system-thread".
type Window struct {
	className *uint16
	hwnd      windows.Handle
	instance  windows.Handle

	img draw.Image
	bmH windows.Handle // bitmap handle

	events chan any
	dndMan *DndMan

	postM struct {
		sync.Mutex
		id int
		m  map[int]any
	}
	cursors struct {
		currentId    int
		hiddenCursor bool
		cache        map[int]windows.Handle
	}
}

func NewWindow(opt *event.WindowOptions) (*Window, error) {
	win := &Window{
		events: make(chan any, 8),
	}
	win.cursors.cache = map[int]windows.Handle{}
	win.postM.m = map[int]any{}
	win.dndMan = NewDndMan()

	// initial size
	rect := image.Rect(0, 0, 1, 1)
	if !opt.Rect.Empty() {
		rect = opt.Rect
	}
	win.ostResizeImage(rect)

	if err := win.initAndSetupLoop(opt); err != nil {
		return nil, err
	}

	return win, nil
}

//----------

func (win *Window) initAndSetupLoop(opt *event.WindowOptions) error {
	initErr := make(chan error)

	go func() {
		// ensure OS thread
		runtime.LockOSThread()
		defer runtime.UnlockOSThread()

		if err := win.ostInitialize(opt); err != nil {
			initErr <- err
			return
		}
		initErr <- nil

		// run event loop in OS thread
		win.ostMsgLoop() // blocks
	}()

	return <-initErr
}

func (win *Window) ostInitialize(opt *event.WindowOptions) error {
	_ = hideConsole()

	// handle containing the window procedure for the class.
	instance, err := _GetModuleHandleW(nil)
	if err != nil {
		return fmt.Errorf("getmodulehandle: %v", err)
	}
	win.instance = instance

	// window class registration
	win.className = UTF16PtrFromString("editorClass")
	wce := _WndClassExW{
		LpszClassName: win.className,
		LpfnWndProc:   windows.NewCallback(win.wndProcCallback),
		HInstance:     win.instance,
		HbrBackground: _COLOR_WINDOW + 1,
		Style:         _CS_HREDRAW | _CS_VREDRAW,
	}
	wce.CbSize = uint32(unsafe.Sizeof(wce))
	if _, err := _RegisterClassExW(&wce); err != nil {
		return fmt.Errorf("registerclassex: %w", err)
	}

	// create window
	x, y, w, h := int32(_CW_USEDEFAULT), int32(_CW_USEDEFAULT), int32(500), int32(500)
	if !opt.Rect.Empty() {
		x, y = int32(opt.Rect.Min.X), int32(opt.Rect.Min.Y)
		w, h = int32(opt.Rect.Dx()), int32(opt.Rect.Dy())
	}

	hwnd, err := _CreateWindowExW(
		0,
		win.className,
		nil, // window title
		_WS_OVERLAPPEDWINDOW,
		x, y, w, h,
		0, 0, win.instance, 0,
	)
	if err != nil {
		return fmt.Errorf("createwindow: %w", err)
	}
	win.hwnd = hwnd

	sw := uint32(_SW_SHOWDEFAULT)
	if opt.StartMaximized {
		sw = _SW_SHOWMAXIMIZED
	}
	_ = _ShowWindowAsync(win.hwnd, int(sw))
	//_ = _UpdateWindow(win.hwnd)

	// cursor: don't set cursor at class struct to avoid auto-restoration
	if err := win.ostSetCursor(event.DefaultCursor); err != nil {
		return err
	}

	if err := win.startDragDrop(); err != nil {
		fmt.Printf("error: dragdrop: %v\n", err)
	}

	return nil
}

//----------

// Called from OS thread.
func (win *Window) ostMsgLoop() {
	// ensure it is instantiated (avoid garbage collection when going throught windows functions that would make go's gc collect the variable)
	msg := _Msg{}

	for {
		ok, err := win.nextMsg(&msg)
		if err != nil {
			win.events <- err
		}
		if !ok {
			break
		}
		win.handleMsg(&msg)
	}
}

func (win *Window) nextMsg(msg *_Msg) (ok bool, _ error) {
	*msg = _Msg{} // reset to zero

	res, err := _GetMessageW(msg, win.hwnd, 0, 0) // wait for next msg
	if err != nil {
		// improve error
		if err2 := windows.GetLastError(); err2 != nil {
			err = fmt.Errorf("%v: %v", err, err2)
		}
		return false, err
	}
	quit := res == 0
	if quit {
		return false, nil
	}
	return true, nil
}

//----------

func (win *Window) NextEvent() (event.Event, bool) {
	ev, ok := <-win.events
	return ev, ok
}

